    /* ✓ 안전: 곱셈 전에 overflow 가능성을 검사한다. */
    if (size != 0 && count > SIZE_MAX / size) {
        /* 곱하면 되돌아올 것이므로 거부 */
        return NULL;
    }

    size_t total = count * size;   /* 이 시점엔 안전함이 보장됨 */
    char *buf = (char *)malloc(total);
    if (buf == NULL) {
        return NULL;
    }
    memset(buf, 'A', total);
    return buf;
