import java.security.Signature;

/**
 * [안전 예제] 전자서명 결과를 반드시 확인 (CWE-347 / KISA 2.10)
 *
 * verify()가 돌려주는 boolean 결과를 조건문으로 반드시 확인하고,
 * 검증에 실패하면 처리 자체를 중단(예외/거부)한다.
 *
 * 안전 지점:
 *   boolean verified = sig.verify(sigBytes);
 *   if (verified) { ... } else { 거부 }
 */
public class Secure {

    /**
     * 메시지와 서명을 받아 검증 결과에 따라 분기한다.
